@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--red:#e84c3d;--cream:#e9e4d8;--muted:#a3a39c;--panel:rgba(13,17,17,.92);--line:rgba(239,231,211,.14)}
*{box-sizing:border-box}
html,body{height:100%;margin:0;overflow:hidden;background:#080b0b;color:var(--cream);font-family:'DM Sans',sans-serif}
canvas{display:block}
#game{position:fixed;inset:0}
#hud{position:fixed;inset:0;pointer-events:none;display:none}
.topbar{position:absolute;left:30px;right:30px;top:24px;display:flex;justify-content:space-between;align-items:flex-start}
.brand{font:800 21px 'Barlow Condensed';letter-spacing:.13em;text-transform:uppercase}
.brand small{display:block;color:#9da19b;font:600 10px 'DM Sans';letter-spacing:.2em;margin-top:3px}
.mission{text-align:right;font:700 12px 'DM Sans';letter-spacing:.12em;text-transform:uppercase}
.mission span{display:block;color:#a8aaa4;font-size:10px;margin-top:5px}
.stats{position:absolute;left:30px;bottom:27px;width:250px}
.statline{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font:700 11px 'DM Sans';letter-spacing:.1em}
.bar{height:7px;background:#282c29;margin-bottom:12px;overflow:hidden}
.bar i{display:block;height:100%;background:#df4d3e;transition:width .2s}
.bar.green i{background:#a7b86f}
.bottomright{position:absolute;right:30px;bottom:27px;text-align:right}
.weaponname{font:800 21px 'Barlow Condensed';letter-spacing:.08em;text-transform:uppercase}
.ammo{font:600 13px 'DM Sans';color:#b0b3ac;margin-top:3px}
.ammo strong{color:#f2eee3;font-size:25px}
.prompt{position:absolute;bottom:35px;left:50%;transform:translateX(-50%);color:#dad9d0;font-size:11px;letter-spacing:.12em;text-transform:uppercase;text-shadow:0 2px 6px #000}
.crosshair{position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%)}
.crosshair:before,.crosshair:after{content:'';position:absolute;background:#eee9d9;box-shadow:0 0 4px #000}
.crosshair:before{width:2px;height:18px;left:8px}
.crosshair:after{height:2px;width:18px;top:8px}
.hit{position:absolute;left:50%;top:50%;width:28px;height:28px;transform:translate(-50%,-50%);color:#fff;font-size:28px;opacity:0;transition:opacity .1s}
.toast{position:absolute;top:22%;left:50%;transform:translateX(-50%);font:800 16px 'Barlow Condensed';letter-spacing:.14em;text-transform:uppercase;text-shadow:0 2px 10px #000;opacity:0;transition:opacity .3s}
.bossbar{position:absolute;top:83px;left:50%;transform:translateX(-50%);width:min(440px,65vw);display:none}
.bossbar label{display:block;text-align:center;font:700 11px 'DM Sans';letter-spacing:.18em;text-transform:uppercase;margin-bottom:7px}
.bossbar .bar{height:9px;background:#342522}
.bossbar .bar i{background:#a92d28}
.overlay{position:fixed;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(5,8,8,.95),rgba(7,10,10,.72) 54%,rgba(5,8,8,.43)),linear-gradient(0deg,rgba(3,5,5,.65),transparent 50%);z-index:5}
.card{width:min(540px,calc(100vw - 36px));padding:36px 40px;background:var(--panel);border:1px solid var(--line);box-shadow:0 22px 90px #0008;backdrop-filter:blur(12px)}
.eyebrow{font-size:10px;letter-spacing:.24em;color:#d36b5a;font-weight:700;text-transform:uppercase}
.title{font:900 clamp(45px,9vw,76px)/.86 'Barlow Condensed';letter-spacing:.015em;text-transform:uppercase;margin:16px 0 18px}
.title span{color:var(--red)}
.desc{font-size:13px;line-height:1.75;color:#b9bbb2;max-width:400px}
.actions{display:flex;gap:12px;margin-top:26px;flex-wrap:wrap}
.btn{border:0;padding:13px 19px;background:var(--red);color:white;font:800 11px 'DM Sans';letter-spacing:.12em;text-transform:uppercase;cursor:pointer;transition:.18s}
.btn:hover{background:#ff6554;transform:translateY(-1px)}
.btn.secondary{border:1px solid #ffffff35;background:#ffffff0b;color:#eee}
.controls{display:flex;gap:14px;flex-wrap:wrap;margin-top:23px;border-top:1px solid var(--line);padding-top:17px;color:#a3a49c;font-size:10px}
.controls b{color:#ebe8dc}
.market{width:min(740px,calc(100vw - 30px));}
.market h2{font:900 38px 'Barlow Condensed';margin:7px 0 4px;text-transform:uppercase}
.marketgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}
.item{padding:14px;border:1px solid var(--line);background:#ffffff06;min-height:120px}
.item h3{font:800 17px 'Barlow Condensed';margin:0 0 5px;text-transform:uppercase}
.item p{font-size:11px;color:#aeb0a8;line-height:1.5;min-height:32px;margin:0 0 12px}
.item .btn{padding:9px 11px;font-size:9px}
.money{color:#d8b775;font-size:12px;font-weight:700}
.market-foot{display:flex;justify-content:space-between;align-items:center;color:#aaa;font-size:12px}
.touch{display:none;position:fixed;inset:0;pointer-events:none;z-index:4}
.touch button{pointer-events:auto;background:#111b;color:white;border:1px solid #ffffff44;border-radius:50%;width:58px;height:58px;font-weight:bold}
.stick{position:absolute;left:24px;bottom:32px;width:125px;height:125px;border-radius:50%;background:#ffffff13;border:1px solid #ffffff35;pointer-events:auto;touch-action:none}
.stick i{display:block;position:absolute;left:42px;top:42px;width:40px;height:40px;border-radius:50%;background:#ffffff55}
.touch .fire{position:absolute;right:23px;bottom:45px;width:76px;height:76px;background:#b33d36a8}
.touch .reload{position:absolute;right:105px;bottom:133px;width:48px;height:48px}
.touch .med{position:absolute;right:25px;bottom:138px;width:48px;height:48px}
@media(max-width:600px){.topbar{left:16px;right:16px;top:15px}
.brand{font-size:16px}
.mission{font-size:10px}
.stats{left:16px;bottom:16px;width:190px}
.bottomright{right:16px;bottom:18px}
.weaponname{font-size:17px}
.ammo strong{font-size:20px}
.prompt{bottom:165px;font-size:9px}
.touch{display:block}
.card{padding:27px 24px}
.marketgrid{grid-template-columns:1fr}
.item{min-height:unset}
.item p{min-height:unset}
.market .card{max-height:90vh;overflow:auto}
}

}

